using Xunit;namespace CRM.ArchitectureTests;public sealed class ReportingInsightsFrontendGuardrailTests{static string Root(){var c=AppContext.BaseDirectory;while(!string.IsNullOrWhiteSpace(c)){if(File.Exists(Path.Combine(c,"CRM.sln")))return c;c=Directory.GetParent(c)?.FullName;}throw new DirectoryNotFoundException();}[Fact]public void Page_IsReadOnly(){var m=File.ReadAllText(Path.Combine(Root(),"frontend","crm-web","src","main.ts"));var a=m.IndexOf("type ReportingInsightMetricView",StringComparison.Ordinal);var b=m.IndexOf("const routes: Routes",a,StringComparison.Ordinal);var s=m[a..b];Assert.Contains("/api/crm/foundation/insights",s);Assert.DoesNotContain(".post<",s);Assert.DoesNotContain(".put<",s);Assert.DoesNotContain(".delete<",s);Assert.DoesNotContain("formControl",s);}}